import hashlib,json,pathlib,subprocess
source=pathlib.Path('C:/Antigravity Projects/Worktrees/Books Arranger/converted-duplicate-20261104')
root=pathlib.Path(__file__).parent
baseline='e6912eb7e43cac35bf26a7a662bc9dc95c0e1d2d'
paths=['tests/test_replacement_jobs.py','tests/test_destination_override.py','tests/test_backend_242.py','tests/test_integration_242.py','tests/test_source_folders.py','tests/test_attention_frontend.js','tests/test_iron_skazka_frontend.js','web/app.js']
records=[]
for name in paths:
    raw=(source/name).read_bytes();old=subprocess.check_output(['git','-C',str(source),'show',baseline+':'+name])
    assert raw.replace(b'\r\n',b'\n')==old.replace(b'\r\n',b'\n'),name
    records.append({'path':name,'raw_sha256':hashlib.sha256(raw).hexdigest(),'lf_sha256':hashlib.sha256(old.replace(b'\r\n',b'\n')).hexdigest()})
(root/'baseline-files.json').write_text(json.dumps({'baseline':baseline,'files':records},indent=2),encoding='utf-8')
def replace(name,old,new):
    file=source/name;raw=file.read_bytes();ending=b'\r\n' if b'\r\n' in raw else b'\n'
    old=old.replace('\n','\r\n' if ending==b'\r\n' else '\n').encode();new=new.replace('\n','\r\n' if ending==b'\r\n' else '\n').encode()
    assert raw.count(old)==1,(name,raw.count(old),old)
    file.write_bytes(raw.replace(old,new))
